import './gta-email-recovery-runtime.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/opportunity-sweep-20261016';const {rows}=JSON.parse(await fs.readFile(dir+'/review.json'));async function all(t,q={}){let a=[];for(let offset=0;;offset+=1000){const p=await db(t,{order:'id.asc',...q,limit:'1000',offset:String(offset)});a.push(...p);if(p.length<1000)return a;}}
const [leads,emails,calls,tasks]=await Promise.all([all('crm_leads'),all('crm_emails'),all('call_recordings',{created_at:'gte.2026-09-16T04:00:00Z',order:'recording_sid.asc'}),all('crm_tasks')]);const norm=p=>String(p||'').replace(/\D/g,'').slice(-10);const out=[];
for(const r of rows){const c=r.contact,terms=c.name==='MVP Condo Management'?['mvp','scott@mvpcondos.com','2265051331']:c.name==='REZA PEYVANDI'?['reza','4162300202']:c.name==='Tailored Rooms Home Staging'?['tailored','angeladumont']:c.name==='Quality Home Staging'?['quality home','fari','5196949188']:c.name==='AURA Contracting'?['aura contracting','2263469950']:c.name==='SIM UPPAL'?['sim uppal','4168780122']:[];if(!terms.length)continue;
const match=v=>terms.some(t=>String(v||'').toLowerCase().includes(t));const ls=leads.filter(l=>match([l.data.name,l.data.email,l.data.phone,l.data.partnerReferralName,l.data.notes].join(' ')));const es=emails.filter(e=>match([e.data.from,e.data.to,e.data.subject].join(' '))||ls.some(l=>l.id===e.data.leadId));const cr=calls.filter(x=>norm(x.phone_number)===norm(c.phone)||ls.some(l=>l.id===x.lead_id));const ta=tasks.filter(t=>t.related_id===c.id||ls.some(l=>l.id===t.related_id)||match(t.title));out.push({name:c.name,contact:c,leads:ls,emails:es,calls:cr,tasks:ta});}
await fs.writeFile(dir+'/enriched.json',JSON.stringify({at:new Date().toISOString(),rows:out},null,2));
for(const r of out)console.log(JSON.stringify({name:r.name,leads:r.leads.map(l=>({id:l.id,deleted:l.deleted,name:l.data.name,stage:l.data.stage,phone:l.data.phone,move:l.data.moveDate,rep:l.data.assignedRepName||l.data.assignedRep,notes:l.data.notes,summary:l.data.partnerLeadSummary,callLogs:l.data.callLogs?.map(x=>({date:x.date,transcript:x.transcript})).slice(-3)})),emails:r.emails.map(e=>({id:e.id,at:e.data.sentAt,d:e.data.direction,subject:e.data.subject,body:e.data.body})),calls:r.calls.map(x=>({at:x.created_at,transcript:x.transcript})),tasks:r.tasks.map(t=>({id:t.id,title:t.title,status:t.status,owner:t.owner_name,description:t.description}))}));
